class OutputColorContract:
    """Own the official demuxer and its pointer until encoder use is finished."""
    def __init__(self, nvc, directory):
        if nvc.__version__ != "2.2.3":
            raise RuntimeError("output_color_requires_qualified_nvc_2_2_3")
        self.path = Path(directory) / "output-color-bt601-limited.mp4"
        self.path.write_bytes(REFERENCE_MP4)
        self.demuxer = None
        try:
            self.demuxer = nvc.CreateDemuxer(filename=str(self.path))
            if (self.demuxer.RFrameRateNum(), self.demuxer.RFrameRateDen()) != (30, 1):
                raise RuntimeError("output_color_reference_must_be_30fps")
            self.pointer = int(self.demuxer.GetAVFormatInputContext())
            if not self.pointer:
                raise RuntimeError("output_color_reference_context_missing")
        except BaseException:
            self.close()
            raise

    def __enter__(self):
        return self

    def __exit__(self, *exc):
        self.close()

    def close(self):
        self.demuxer = None
        self.pointer = 0
        self.path.unlink(missing_ok=True)

    @property
    def encoder_options(self):
        if self.demuxer is None:
            raise RuntimeError("output_color_context_already_closed")
        return {"source_av_format_context": self.pointer}
